func TestCrossVal_ADX(t *testing.T) {
	calc := monitor.NewIndicatorCalculator()
	sym, _ := domain.NewSymbol("AAPL")
	snap := feedRefBars(t, calc, sym)

	// ADX implementations vary significantly due to initialization/smoothing differences.
	// We verify directional agreement (both indicate weak trend) rather than exact match.
	assert.InDelta(t, refADX, snap.ADX, 15.0,
		"ADX: ours=%.2f, pandas-ta=%.2f (wide tolerance — initialization differs)", snap.ADX, refADX)
	// Both should agree this is a weak/no trend (< 30)
	assert.Less(t, snap.ADX, 40.0, "ADX should indicate weak trend for this choppy data")
}
